 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The three-cell motif on the top edge seeds three colored paths.
    seeds = [(0, c, grid[0][c]) for c in range(w) if grid[0][c] != 0]
    for sr, sc, color in seeds:
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color and (r, c) != (sr, sc)]
        if pts:
            # The matching remote point is joined to the motif by an L-shaped path.
            r, c = pts[0]
            for rr in range(min(sr, r), max(sr, r) + 1):
                out[rr][sc] = color
            for cc in range(min(sc, c), max(sc, c) + 1):
                out[r][cc] = color
        else:
            # A motif color without a remote endpoint continues down to the edge.
            for rr in range(sr, h):
                out[rr][sc] = color
    return out
